import{_ as n,o as s,c,a as e,e as i}from"./app.547295de.js?v=20260806-v2.9.3-repo-urls";const _={};const h=i(`<h2 id="更新日志" tabindex="-1"><a class="header-anchor" href="#更新日志" aria-hidden="true">#</a> 更新日志</h2><p align="center"><a href="https://github.com/storyAura/lora-scripts-story-next" style="margin:2px;"><img alt="GitHub Repo stars" src="https://img.shields.io/github/stars/storyAura/lora-scripts-story-next"></a><a href="https://github.com/storyAura/lora-scripts-story-next" style="margin:2px;"><img alt="GitHub forks" src="https://img.shields.io/github/forks/storyAura/lora-scripts-story-next"></a><a href="https://raw.githubusercontent.com/storyAura/lora-scripts-story-next/master/LICENSE" style="margin:2px;"><img src="https://img.shields.io/github/license/storyAura/lora-scripts-story-next" alt="license"></a><a href="https://github.com/storyAura/lora-scripts-story-next/releases" style="margin:2px;"><img src="https://img.shields.io/github/v/release/storyAura/lora-scripts-story-next?color=blueviolet&amp;include_prereleases" alt="release"></a></p><h3 id="版本记录" tabindex="-1"><a class="header-anchor" href="#版本记录" aria-hidden="true">#</a> 版本记录</h3><div class="sd-changelog-banner"><img src="/assets/changelog-banner.webp?v=20260805-nst" alt="Next Story Trainer" loading="lazy" width="960" height="420"></div><h4 id="v2-9-3" tabindex="-1"><a class="header-anchor" href="#v2-9-3" aria-hidden="true">#</a> v2.9.3</h4><ul><li><strong>GSoKR</strong>：BF16 合并路径修正，微小更新不再被加基座再减回去吸收；补数值回归并同步 vendored LyCORIS</li><li><strong>品牌素材</strong>：落地 Next Story Trainer Logo / favicon / 首页图 / Changelog 横幅 / README 封面</li><li><strong>英文界面</strong>：Chrome / Schema / Help 外置词表；Markdown 字段说明按整块翻译，避免中文残留</li><li><strong>发布身份</strong>：联系方式与 Github 指向 storyAura；LoRA 训练页介绍与 hydration 对齐</li><li><strong>版本缓存</strong>：全站 <code>sd-trainer-brand.js?v=</code> 与 <code>VERSION</code> 对齐；其余 i18n 走 SPA 缓存键</li></ul><h4 id="v2-9-2" tabindex="-1"><a class="header-anchor" href="#v2-9-2" aria-hidden="true">#</a> v2.9.2</h4><ul><li><strong>严重：防双训练</strong>：停止后再开训时，旧 Accelerate/训练进程树杀干净后才允许下一场，避免 Loss/Epoch 乱跳、预览「最新图」来自旧 run</li><li><strong>监控数据对齐</strong>：参数绑定当前任务 config；Loss/学习率与 TensorBoard scalar 同源；Epoch 显示为当前/总轮数</li></ul><h4 id="v2-9-1" tabindex="-1"><a class="header-anchor" href="#v2-9-1" aria-hidden="true">#</a> v2.9.1</h4><ul><li><strong>长驻稳定性</strong>：训练日志直播（SSE）超过 15000 行不再断更；任务与日志历史占用有上限，挂机多天不再累积内存；日志页仅保留最近 5000 行</li><li><strong>监控页轻量化</strong>：TensorBoard Loss 曲线按事件文件缓存解析，文件未变不再每次轮询全量重读</li><li><strong>T-GLoKR</strong>：时间步门控算法独立选项；预览采样逐步注入时间步，预览图与训练行为一致</li><li><strong>预览调度器</strong>：新增 Beta 调度器（ComfyUI 同款 Beta(0.6,0.6)）</li><li><strong>配置修复</strong>：lora_type 切换 / 读取历史参数不再表单消失或提交失败</li></ul><h4 id="v2-9-0" tabindex="-1"><a class="header-anchor" href="#v2-9-0" aria-hidden="true">#</a> v2.9.0</h4><ul><li><strong>Anima Fast</strong>：高分辨率自动计算 <code>max_bucket_reso</code>，开放桶分辨率与步长选项</li><li><strong>LoKr</strong>：参数预览 / 下载配置不再出现 <code>conv_dim=undefined</code> 等无效值</li><li><strong>本地打标</strong>：wd-vit-v3 / wd14-moat-v2 本地模型齐全时不再联网</li><li><strong>整合包</strong>：用户数据目录 junction 化，移动整合包后自动修复</li></ul><h4 id="v2-8-2" tabindex="-1"><a class="header-anchor" href="#v2-8-2" aria-hidden="true">#</a> v2.8.2</h4><ul><li><strong>整合包</strong>：发布 <code>SD-Trainer-v2.8.2.7z</code>；内置默认 WD 打标模型（<code>tagger-models/wd14/</code>）与 SDXL tokenizer 缓存</li><li><strong>SDXL 训练修复</strong>：修正 <code>sdxl-lora</code> 路由；整合包离线 tokenizer；训练子进程启动修复</li><li><strong>打标修复</strong>：数据集打标开箱即用；加载超时与 CUDA / CPU 回退</li><li><strong>预览图修复</strong>：旧 TOML 自动补 <code>enable_preview</code>；Fast 安装完成后自动刷新，恢复参数预览</li><li><strong>训练配置导入修复</strong>：全量导入保留数值类型；参数预览与下载配置序列化修复</li></ul><h4 id="v2-7-0" tabindex="-1"><a class="header-anchor" href="#v2-7-0" aria-hidden="true">#</a> v2.7.0</h4><ul><li><strong>Anima LoRA Fast 模式</strong>：侧栏「Anima LoRA → Fast 模式」，可选插件 <code>anima_lora</code>（页内安装、独立 venv）</li><li>训练监控同步 Fast Loss / 进度 / 预览；文档 <code>docs/anima-fast.md</code></li><li>同参对标约 <strong>2.5×</strong> 加速（4090；标准 ≈7.1 s/step vs Fast ≈2.8 s/step）</li><li>整合包<strong>不预装</strong>插件 venv，首次在 Fast 页安装</li></ul><h4 id="v2-6-0" tabindex="-1"><a class="header-anchor" href="#v2-6-0" aria-hidden="true">#</a> v2.6.0</h4><ul><li><strong>Anima 全量微调</strong>：侧栏「全量微调 → Anima Finetune」，路由 <code>anima-finetune</code> → <code>anima_train.py</code></li><li>训练监控正确显示 <strong>Anima Finetune</strong>（不再误标为 LoRA）</li><li>文档与示例：<code>docs/anima-backend.md</code>、<code>docs/examples/anima-full-finetune.toml</code></li><li>显存参考：4090 实测专用显存约 23–24 GB（与 LoRA 的 12GB 档不同）</li></ul><h4 id="v2-5-3" tabindex="-1"><a class="header-anchor" href="#v2-5-3" aria-hidden="true">#</a> v2.5.3</h4><ul><li>便携包依赖健康检查、侧栏版本号（<a href="https://github.com/wochenlong/lora-scripts-next/issues/54" target="_blank" rel="noopener noreferrer">#54</a>）</li></ul><h4 id="v2-5-0" tabindex="-1"><a class="header-anchor" href="#v2-5-0" aria-hidden="true">#</a> v2.5.0</h4><ul><li>UI 焕新：侧栏导航重构，训练 / 工具 / 帮助分区清晰</li><li>首页传送门：卡片式入口快速跳转训练、监控、新手上路</li><li>训练监控仪表盘：GPU 实时指标、总步数、训练参数速查</li><li>CSS 去重清理（~1660 行冗余代码）</li></ul><h4 id="v2-4-0" tabindex="-1"><a class="header-anchor" href="#v2-4-0" aria-hidden="true">#</a> v2.4.0</h4><ul><li>训练子进程环境隔离，NaN 过滤，采样保护，attn_mode 降级</li><li>路径规范化；整合包 tkinter 修复</li></ul><h4 id="v2-3-0" tabindex="-1"><a class="header-anchor" href="#v2-3-0" aria-hidden="true">#</a> v2.3.0</h4><ul><li>TensorBoard 同源 Loss 曲线；训练参数速查；日志同步到监控页</li><li>整合包：跳过 triton-windows；run_gui 启动日志；跨盘监控修复</li></ul><h4 id="v2-1-0" tabindex="-1"><a class="header-anchor" href="#v2-1-0" aria-hidden="true">#</a> v2.1.0</h4><ul><li>Flash Attention 2 预构建 Wheel（Windows 免编译）</li><li>按步数保存；LoKr 显示修复；跨盘监控修复</li></ul><h4 id="v2-0-0" tabindex="-1"><a class="header-anchor" href="#v2-0-0" aria-hidden="true">#</a> v2.0.0</h4><ul><li>Windows 便携包首发；Flash Attention 自动加速；AMD 提示；bf16 修复</li></ul><h4 id="v1-next" tabindex="-1"><a class="header-anchor" href="#v1-next" aria-hidden="true">#</a> 基于原版的改进</h4><ul><li>Anima 训练（LoRA / LoKr / T-LoRA）</li><li>交互式 Loss 曲线；实时训练监控（端口 6008）</li><li>Anima 后端迁移至 kohya-ss/sd-scripts</li></ul><h3 id="原版更新日志" tabindex="-1"><a class="header-anchor" href="#原版更新日志" aria-hidden="true">#</a> 原版更新日志</h3><p>本项目 Fork 自 <a href="https://github.com/Akegarasu/lora-scripts" target="_blank" rel="noopener noreferrer">Akegarasu/lora-scripts</a>，完整记录见仓库根目录 <a href="https://github.com/storyAura/lora-scripts-story-next/blob/main/CHANGELOG.md" target="_blank" rel="noopener noreferrer">CHANGELOG.md</a>；整合包补充说明见 <a href="https://github.com/storyAura/lora-scripts-story-next/blob/main/docs/portable-getting-started.md" target="_blank" rel="noopener noreferrer">docs/portable-getting-started.md</a>。</p>`);function u(){return s(),c("div",null,[h])}var x=n(_,[["render",u],["__file","changelog.html.vue"]]);export{x as default};
